"""Offline browser tests for the supplied Spine 3.8.99 rig. No npm/CDN needed.
Optional developer dependencies: Python Playwright and Chromium.
Run: python3 tests/spine.test.py
"""
from pathlib import Path
import base64, hashlib, json, os, time
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1]
HTML=(ROOT/'PLAY.html').read_text().replace('<head>','<head><script>window.__KEMET_TEST__=true;</script>',1)
checks=[];errors=[];warnings=[];network=[]
def ok(name,evidence=True):
    assert evidence,name
    checks.append({'test':name,'pass':True,'evidence':evidence})
    print('PASS',name,flush=True)
with sync_playwright() as p:
    browser=p.chromium.launch(executable_path=os.environ.get('CHROMIUM_PATH','/usr/bin/chromium'),headless=True,args=['--no-sandbox'])
    page=browser.new_page(viewport={'width':1600,'height':900},device_scale_factor=1)
    page.on('pageerror',lambda e:errors.append(str(e)))
    page.on('console',lambda m:warnings.append(m.text) if m.type in ['warning','error'] else None)
    page.on('request',lambda r:network.append(r.url) if r.url.startswith(('http:','https:')) else None)
    page.set_content(HTML,wait_until='load',timeout=45000)
    page.wait_for_function('window.KEMET?.ready',timeout=30000)
    page.evaluate('window.P=KEMET_TEST.scene.spinePlayer;window.S=KEMET_TEST.scene;window.G=KEMET_TEST.game;window.A=KEMET_TEST.app')
    ok('Beetle update starts with the unchanged Pixi/GSAP renderer',page.evaluate('KEMET.version==="royal-1.1.2-beetle-landings"&&KEMET.ready'))
    ok('Supplied 3.8.99 skeleton has 81 bones and 93 slots',page.evaluate('P.stats().bones===81&&P.stats().slots===93&&P.stats().version==="3.8.99"'))
    ok('Both authored animations are present',page.evaluate('JSON.stringify([...P.data.animations.keys()])===JSON.stringify(["action","idle"])'))
    ok('Authored durations are preserved',page.evaluate('P.data.animations.get("idle").duration===2&&P.data.animations.get("action").duration===1.6667'))
    ok('Mesh, region, linked-mesh and clipping attachments are parsed',page.evaluate('new Set([...P.data.attachments.values()].map(a=>a.type)).size===4'))
    ok('98 drawable attachments and 1876 nondegenerate triangles',page.evaluate('P.data.meshCount===98&&P.data.triangleCount===1876'))
    ok('Outside host uses the full-body live skeletal texture',page.evaluate('S.spineHost.texture===P.unframedView.texture&&S.spineHost.visible&&S.hostLayer.visible'))
    ok('Normal Anubis reel symbols use the live skeleton texture source',page.evaluate('S.reels.flatMap(r=>r.views).filter(v=>v.id==="anubis").every(v=>v.sprite.texture.source===P.texture.source)'))
    ok('No extra onscreen renderer/context created',page.evaluate('document.querySelectorAll("#canvasHost canvas").length===1'))
    page.wait_for_timeout(650)
    page.screenshot(path=str(ROOT/'tests/spine-desktop.png'))
    page.evaluate('A.stop();P.name="idle";P.time=0;P.mixFrom=null;P.renderPose()')
    idle0=page.evaluate('({r:P.skeleton.bones[P.data.boneMap.get("body1")].rotation,pixels:P.canvas.toDataURL(),scale:S.spineHost.scale.x})')
    page.evaluate('P.time=1;P.renderPose()')
    idle1=page.evaluate('({r:P.skeleton.bones[P.data.boneMap.get("body1")].rotation,pixels:P.canvas.toDataURL(),scale:S.spineHost.scale.x})')
    ok('Idle changes actual bone rotation, not sprite scaling',idle0['r']!=idle1['r'] and idle0['scale']==idle1['scale'])
    ok('Idle produces different rendered pixels',idle0['pixels']!=idle1['pixels'])
    ok('Eyelid alpha follows the authored blink timeline',page.evaluate('(()=>{let i=P.data.slotMap.get("character_symbol_anubis_head_eyelid_left_close_top");return P.data.sample("idle",.4).colors[i][3]===0&&P.data.sample("idle",.6).colors[i][3]>.99;})()'))
    ok('Deform timeline has nonzero weighted vertex offsets',page.evaluate('[...P.data.sample("idle",.5).deform.values()].some(a=>a.some(v=>Math.abs(v)>.01))'))
    ok('Flame swaps linked atlas attachments from the export',page.evaluate('(()=>{let i=P.data.slotMap.get("fire-fx-comp6");return P.data.sample("idle",.07).names[i]==="back_fire_2"&&P.data.sample("idle",.14).names[i]==="back_fire_3";})()'))
    page.evaluate('P.name="action";P.time=.9;P.mixFrom=null;P.renderPose()')
    action=page.evaluate('({pixels:P.canvas.toDataURL(),x:P.skeleton.bones[P.data.boneMap.get("hand_left")].worldX})')
    page.evaluate('P.name="idle";P.time=.9;P.renderPose()')
    ok('Action moves the hand bone and changes the rendered pose',action['x']!=page.evaluate('P.skeleton.bones[P.data.boneMap.get("hand_left")].worldX') and action['pixels']!=idle1['pixels'])
    page.evaluate('P.play("action",{mix:0});for(let i=0;i<40;i++)P.update(.05,{})')
    ok('Action automatically returns to looping idle',page.evaluate('P.name==="idle"&&P.loop'))
    page.evaluate('P.action("test-mix");P.update(.05,{});window.beforeMix=P.skeleton.bones[P.data.boneMap.get("body1")].rotation;P.play("idle");P.renderPose()')
    ok('Crossfade begins at the outgoing pose without a pop',page.evaluate('Math.abs(beforeMix-P.skeleton.bones[P.data.boneMap.get("body1")].rotation)<1e-8'))
    page.evaluate('P.update(.05,{reducedMotion:true});window.frozenFrames=P.frames;window.frozenPose=P.canvas.toDataURL();for(let i=0;i<8;i++)P.update(.05,{reducedMotion:true})')
    ok('Reduced motion freezes skeletal playback',page.evaluate('P.frames===frozenFrames&&P.canvas.toDataURL()===frozenPose'))
    page.evaluate('P.update(.05,{});window.hiddenFrames=P.frames;for(let i=0;i<8;i++)P.update(.05,{visible:false})')
    ok('Hidden mobile character does not rasterize invisible frames',page.evaluate('P.frames===hiddenFrames'))
    page.evaluate('P.play("idle",{mix:0});A.start()')
    # Native Pixi pointer event; the outside character is cosmetic and cannot alter balance.
    before=page.evaluate('G.session.snapshot()');actions=page.evaluate('P.actionCount')
    page.mouse.click(126,480)
    ok('Clicking the outside character triggers its action without changing game state',page.evaluate('P.actionCount')==actions+1 and page.evaluate('G.session.snapshot()')==before)
    page.evaluate('gsap.globalTimeline.timeScale(8);G.spin({grid:[["ankh","ankh","ankh"],["eye","eye","eye"],["necklace","necklace","necklace"],["eye","eye","eye"],["ankh","ankh","ankh"]]})')
    page.wait_for_function('G.phase==="IDLE"',timeout=15000)
    ok('Spin start triggers the skeletal action',page.evaluate('P.events.some(e=>e.reason==="spin")'))
    page.evaluate('G.spin({grid:Array.from({length:5},()=>["ankh","ankh","ankh"])})')
    page.wait_for_function('G.phase==="IDLE"',timeout=15000)
    ok('Winning result triggers the skeletal reaction',page.evaluate('P.events.some(e=>e.reason==="win")'))
    ok('Large win triggers the same authored action clip',page.evaluate('P.events.some(e=>e.reason==="big-win")'))
    page.evaluate('S.setTemple(true)')
    ok('Temple entry is connected to the action clip',page.evaluate('P.events.some(e=>e.reason==="temple-entry")'))
    page.evaluate('async()=>{await S.expandGuardians([0,2,4]);}')
    ok('Expanded guardians trigger the action clip',page.evaluate('P.events.some(e=>e.reason==="guardian-expansion")'))
    ok('Three framed guardians and full-body host share one evaluated skeleton',page.evaluate('P.sprites.size===4&&S.guardians.length===3'))
    texture_id=page.evaluate('P.texture.uid')
    page.evaluate('async()=>{for(let i=0;i<12;i++){S.clearGuardians();await S.expandGuardians([0,1,2,3,4]);S.clearGuardians();}}')
    ok('Repeated expansion/cleanup leaves only the host view',page.evaluate('P.sprites.size===1&&S.guardianLayer.children.length===0'))
    ok('Expansion does not recreate the shared character texture',page.evaluate('P.texture.uid')==texture_id)
    # Showcase/screenshot inspection is developer-only and does not save staged outcomes.
    page.evaluate('async()=>{G.clearNext();S.clearWins();await S.expandGuardians([1,3]);gsap.globalTimeline.timeScale(1);document.getElementById("showcaseBar").hidden=false;document.getElementById("resultText").textContent="LIVE SPINE · ANUBIS GUARDIANS";A.stop();P.name="action";P.time=.88;P.mixFrom=null;P.renderPose();A.render();}')
    page.screenshot(path=str(ROOT/'tests/spine-guardians.png'))
    for w,h in [(390,844),(844,390),(1280,720),(1920,1080)]:
        page.set_viewport_size({'width':w,'height':h});page.wait_for_timeout(100)
        b=page.locator('#spinBtn').bounding_box()
        ok(f'Spin controls remain inside {w}×{h}',bool(b and b['x']>=0 and b['y']>=0 and b['x']+b['width']<=w+1 and b['y']+b['height']<=h+1))
        page.evaluate('A.render()')
        if w==390:page.screenshot(path=str(ROOT/'tests/spine-mobile.png'))
    ok('No JavaScript errors',not errors)
    ok('No console errors or warnings',not warnings)
    ok('Standalone remains fully offline',not network)
    report={'checks':checks,'counts':{'passed':len(checks)},'renderer':page.evaluate('KEMET.renderer'),'spine':page.evaluate('P.stats()'),'page_errors':errors,'console_warnings':warnings,'external_requests':network,'scope':'Headless Chromium; actual Canvas2D backend. Live Spine-export bone/mesh playback tested. User GPU and other browsers not tested.'}
    (ROOT/'tests/spine-results.json').write_text(json.dumps(report,indent=2))
    print(json.dumps(report,indent=2),flush=True)
    browser.close()
